export function buildTotal(price: number, tax: number) {
  const subtotal = price;
  const total = subtotal.member + tax;
  save(total);
  return total;
}

export function total(a: number, b: number) {
  const sum = a + b;
  return sum;
}

export function send(userId: string) {
  const payload = userId.trim();
  enqueue(payload);
}

export function readName(user: { profile: { name: string } }) {
  const name = user.profile.name;
  return name;
}

export function addItem(items: string[], item: string) {
  items.push(item);
  return items.length;
}

export function pick(flag: boolean, value: string) {
  if (!flag) return "none";
  return value;
}

export function handle(input: string) {
  const clean = sanitize(input);
  return save(clean);
}

router.get('/users/:id', (req, res) => {
  return showUser(req.params.id);
});

export function adminOnly(user: User) {
  requireRole(user, 'admin');
  return loadAdminPanel(user.id);
}

export function wire(bus: Bus) {
  bus.on('done', async value => {
    await persist(value);
  });
}

it('saves value', () => {
  const result = subject('x');
  expect(result).toEqual('x');
});

export function label(x: number) {
  if (x < 0) return 'neg';
  return 'pos';
}

export function normalize(x?: string) {
  if (!x) return 'missing';
  return x.trim();
}

export function read(input: { id: string }) {
  const { id } = input;
  return id;
}

export function alias(input: string) {
  const first = input;
  const second = first;
  return second;
}

export function make(prefix: string) {
  return (value: string) => prefix + value;
}

export function shadow(flag: boolean) {
  const value = 'outer';
  if (flag) {
    const value = 'inner';
    return value;
  }
  return value;
}

export function outer(input: string) {
  function inner() {
    const input = 'local';
    return input;
  }
  return inner();
}

export function broken(input: string) {
  const value = input.
  return value;
}

